import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Oct 3, 2016 | 12:28:10 PM
 * <pre>
 * <u>Alternative Version</u>
 *
 * </pre>
 *
 * @author Essiennta Emmanuel (colourfulemmanuel@gmail.com)
 */
public class ProblemB {

    private void run(char[] data, PrintWriter out) {
        int idx = 0;
        int maxLen = 0;
        int pairs = 0;
        boolean insideParenthesis = false;
        while (idx < data.length) {
            if (data[idx] == '(') {
                insideParenthesis = true;
            } else if (data[idx] == ')') {
                insideParenthesis = false;
            } else if (Character.isLetter(data[idx]))
                idx--;
            if (insideParenthesis) {
                while (++idx != data.length && data[idx] != ')' && !Character.isLetter(data[idx]));
                if (idx == data.length || !Character.isLetter(data[idx])) {
                    continue;
                }
                while (Character.isLetter(data[++idx]));
                pairs++;
            } else {
                while (++idx != data.length && data[idx] != '(' && !Character.isLetter(data[idx]));
                if (idx == data.length || !Character.isLetter(data[idx])) {
                    continue;
                }
                int startIdx = idx;
                while (++idx != data.length && Character.isLetter(data[idx]));
                maxLen = Math.max(maxLen, idx - startIdx);
            }
        }
        out.println(maxLen + " " + pairs);
    }

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            br.readLine();
            new ProblemB().run(br.readLine().toCharArray(), pw);
        }
    }
}
